import{_ as a,c as i,o,j as n,Y as s,t as r}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"git-var | x-cmd man (git man1) | Show a Git logical variable","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-var - Show a Git logical variable","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-var | x-cmd man (git man1) | Show a Git logical variable"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-var - Show a Git logical variable"}]]},"headers":[],"params":{"isMan":true,"man":"git-var","category":"git man1","desc":"Show a Git logical variable"},"relativePath":"git/man1/git-var.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-var.md"},h={class:"visually-hidden"};function g(t,e,c,p,d,m){return o(),i("div",null,[n("h1",h,r(t.$params.man),1),e[0]||(e[0]=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-var - Show a Git logical variable</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (-l </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">variable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;)</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Prints a Git logical variable. Exits with code 1 if the variable has no value.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-l</p><blockquote><p>Cause the logical variables to be listed. In addition, all the variables of the Git configuration file .git/config are listed as well. (However, the configuration variables listing functionality is deprecated in favor of <strong>git config -l</strong>.)</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><pre><code>$ git var GIT_AUTHOR_IDENT
Eric W. Biederman &lt;ebiederm@lnxi.com&gt; 1121223278 -0600
</code></pre></blockquote><h2 id="variables" tabindex="-1">VARIABLES <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;VARIABLES&quot;">​</a></h2><p>GIT_AUTHOR_IDENT</p><blockquote><p>The author of a piece of code.</p></blockquote><p>GIT_COMMITTER_IDENT</p><blockquote><p>The person who put a piece of code into Git.</p></blockquote><p>GIT_EDITOR</p><blockquote><p>Text editor for use by Git commands. The value is meant to be interpreted by the shell when it is used. Examples: <strong>~/bin/vi</strong>, <strong>$SOME_ENVIRONMENT_VARIABLE</strong>, <strong>&quot;C:\\Program Files\\Vim\\gvim.exe&quot; --nofork</strong>. The order of preference is the <strong>$GIT_EDITOR</strong> environment variable, then <strong>core.editor</strong> configuration, then <strong>$VISUAL</strong>, then <strong>$EDITOR</strong>, and then the default chosen at compile time, which is usually <em>vi</em>.</p></blockquote><p>GIT_SEQUENCE_EDITOR</p><blockquote><p>Text editor used to edit the <em>todo</em> file while running <strong>git rebase -i</strong>. Like <strong>GIT_EDITOR</strong>, the value is meant to be interpreted by the shell when it is used. The order of preference is the <strong>$GIT_SEQUENCE_EDITOR</strong> environment variable, then <strong>sequence.editor</strong> configuration, and then the value of <strong>git var GIT_EDITOR</strong>.</p></blockquote><p>GIT_PAGER</p><blockquote><p>Text viewer for use by Git commands (e.g., <em>less</em>). The value is meant to be interpreted by the shell. The order of preference is the <strong>$GIT_PAGER</strong> environment variable, then <strong>core.pager</strong> configuration, then <strong>$PAGER</strong>, and then the default chosen at compile time (usually <em>less</em>).</p></blockquote><p>GIT_DEFAULT_BRANCH</p><blockquote><p>The name of the first branch created in newly initialized repositories.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-commit-tree</strong>(1) <strong>git-tag</strong>(1) <strong>git-config</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,28))])}const E=a(l,[["render",g]]);export{b as __pageData,E as default};
